import { tags } from "typia";

import { IShoppingMallSeller } from "./IShoppingMallSeller";

/**
 * Represents a single row within a seller payout statement on the shopping mall
 * platform.
 *
 * Each row corresponds to a concrete payout item included in a seller payout
 * batch, typically linked to one or more orders, order lines, or settlement
 * report rows. It is used to present detailed payout breakdowns to sellers and
 * finance teams.
 *
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export type IShoppingMallSellerPayoutStatementRow = {
  /**
   * Unique identifier of the payout statement row.
   *
   * Used to uniquely reference a specific payout item within the system.
   */
  id: string & tags.Format<"uuid">;

  /** Seller who receives the payout amount represented by this statement row. */
  seller: IShoppingMallSeller.ISummary;

  /**
   * Identifier of the payout batch that groups this statement row.
   *
   * All rows with the same payout_batch_id belong to the same settlement
   * transfer, such as a bank transfer or remittance batch.
   */
  payout_batch_id: string & tags.Format<"uuid">;

  /**
   * Sequence number of this row within the payout batch, used for stable
   * ordering in statements.
   */
  payout_sequence_number: number & tags.Type<"int32">;

  /**
   * ISO 4217 currency code of the payout amounts for this row.
   *
   * Examples: "USD", "KRW", "EUR".
   */
  currency: string;

  /**
   * Total gross amount payable to the seller in this payout row before
   * deductions.
   *
   * Derived from the sum of positively contributing settlements such as
   * completed order revenue.
   */
  gross_payable_amount: number;

  /**
   * Total platform fee amount deducted in this payout row.
   *
   * Represents commissions and other platform service fees charged against
   * the seller’s gross payable amount.
   */
  platform_fee_amount: number;

  /**
   * Net adjustment amount due to refunds and chargebacks associated with the
   * items covered by this payout row.
   *
   * Usually a negative amount (deduction), but may be positive if prior
   * over-deductions are being corrected.
   */
  refund_and_chargeback_adjustment_amount: number;

  /**
   * Tax amount withheld by the platform for this payout row.
   *
   * Covers withholding tax or other tax obligations the platform is
   * responsible to remit on behalf of the seller.
   */
  tax_withheld_amount: number;

  /**
   * Additional adjustments applied to this payout row that are not covered by
   * platform fees, refunds, chargebacks, or tax.
   *
   * Examples include manual corrections, promotional incentives, or
   * penalties.
   */
  other_adjustment_amount: number;

  /**
   * Final net payout amount to be transferred to the seller for this
   * statement row.
   *
   * Calculated as gross_payable_amount minus all deductions and plus/minus
   * any adjustments.
   */
  net_payout_amount: number;

  /**
   * Inclusive start datetime of the settlement period covered by this payout
   * row in ISO 8601 format.
   */
  settlement_period_start: string & tags.Format<"date-time">;

  /**
   * Exclusive end datetime of the settlement period covered by this payout
   * row in ISO 8601 format.
   */
  settlement_period_end: string & tags.Format<"date-time">;

  /**
   * List of identifiers of settlement report rows that were aggregated to
   * produce this payout statement row.
   *
   * Provides traceability between detailed settlement calculations and final
   * payout entries.
   */
  related_settlement_report_row_ids: (string & tags.Format<"uuid">)[];

  /**
   * Payment method used to transfer the payout amount to the seller.
   *
   * Examples: "bank_transfer", "virtual_account", "e_wallet".
   */
  payout_method: string;

  /**
   * Current status of the payout represented by this statement row.
   *
   * Typical values may include:
   *
   * - "pending": Payout scheduled but not yet initiated
   * - "processing": Payout in progress
   * - "completed": Payout successfully transferred
   * - "failed": Payout attempt failed
   * - "cancelled": Payout was cancelled or reversed.
   */
  payout_status: string;

  /**
   * Datetime when the payout transfer was initiated in ISO 8601 format.
   *
   * May be null if payout has not yet been initiated.
   */
  payout_initiated_at?: (string & tags.Format<"date-time">) | undefined;

  /**
   * Datetime when the payout transfer was successfully completed in ISO 8601
   * format.
   *
   * May be null if payout has not yet completed or has failed.
   */
  payout_completed_at?: (string & tags.Format<"date-time">) | undefined;
};
